<h2>Meu carrinho</h2><?php if(!$items): ?><p>Seu carrinho está vazio. <a href="?r=products">Ver produtos</a></p><?php else: ?>
<table><thead><tr><th>Produto</th><th>Preço</th><th>Quantidade</th><th>Subtotal</th><th></th></tr></thead><tbody>
<?php foreach($items as $p): ?><tr><td><?= htmlspecialchars($p['name']) ?></td><td>R$ <?= number_format((float)$p['price'],2,',','.') ?></td><td><form class="inline" method="post" action="?r=cart/update"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf) ?>"><input type="hidden" name="product_id" value="<?= (int)$p['id'] ?>"><input class="qty" type="number" name="quantity" min="1" max="<?= (int)$p['stock'] ?>" value="<?= (int)$p['quantity'] ?>"><button>Atualizar</button></form></td><td>R$ <?= number_format((float)$p['subtotal'],2,',','.') ?></td><td><form method="post" action="?r=cart/remove"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf) ?>"><input type="hidden" name="product_id" value="<?= (int)$p['id'] ?>"><button class="danger">Remover</button></form></td></tr><?php endforeach; ?></tbody></table>
<h3>Total: R$ <?= number_format($total,2,',','.') ?></h3><div class="actions"><form method="post" action="?r=cart/clear"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf) ?>"><button class="danger">Esvaziar carrinho</button></form><form method="post" action="?r=orders/checkout"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf) ?>"><button>Finalizar pedido</button></form></div><p class="hint">O checkout requer um usuário autenticado em $_SESSION['user_id']; veja README.md.</p><?php endif; ?>
